import{_ as s,b as n,f as e,I as l}from"./chunks/framework.DYvp_Vyw.js";const u=JSON.parse('{"title":"Matlab学习笔记002 - MATLAB程序设计","description":"","frontmatter":{"title":"Matlab学习笔记002 - MATLAB程序设计","date":"2025-05-05T17:05:23.000Z","tags":["数学建模","Matlab"],"head":[["meta",{"name":"descriptionx x x","content":"vitepress-theme-bluearchive Tags"}],["meta",{"name":"keywords","content":"vitepress theme bluearchive Tags"}]]},"headers":[],"relativePath":"posts/Matlab-Own-Study-002.md","filePath":"posts/Matlab-Own-Study-002.md"}'),p={name:"posts/Matlab-Own-Study-002.md"};function i(r,a,o,t,c,d){return e(),n("div",null,a[0]||(a[0]=[l(`<p>自己学习后整理的笔记（实时更新）</p><hr><blockquote><p>MATLAB有两种工作方式： 1.交互式的命令行工作方式 2.M文件的程序工作方式</p></blockquote><h1 id="一-m文件" tabindex="-1">一. M文件 <a class="header-anchor" href="#一-m文件" aria-label="Permalink to &quot;一. M文件&quot;">​</a></h1><p>用MATLAB语言编写的程序，称为M文件。 M文件有两类：命令文件和函数文件。</p><ul><li>命令文件：没有输入参数，也不返回输出　　参数。</li><li>函数文件：可以输入参数，也可返回输出参数。</li></ul><h2 id="_1-m文件的建立与编辑" tabindex="-1">１．M文件的建立与编辑 <a class="header-anchor" href="#_1-m文件的建立与编辑" aria-label="Permalink to &quot;１．M文件的建立与编辑&quot;">​</a></h2><ul><li><p>建立新的M文件： 从MATLAB命令窗口的File菜单中选择New菜单项，再选择M-file命令。</p></li><li><p>编辑已有的M文件： 从MATLAB命令窗口的Flie菜单中选择Open M-file命令。</p></li></ul><h2 id="_2-命令文件" tabindex="-1">２．命令文件 <a class="header-anchor" href="#_2-命令文件" aria-label="Permalink to &quot;２．命令文件&quot;">​</a></h2><p>将需要运行的命令编辑到一个命令文件中，然后在MATLAB命令窗口输入该命令文件的名字，就会顺序执行命令文件中的命令。</p><h1 id="二-数据的输入输出" tabindex="-1">二．数据的输入输出 <a class="header-anchor" href="#二-数据的输入输出" aria-label="Permalink to &quot;二．数据的输入输出&quot;">​</a></h1><h3 id="_1-input函数-用于向计算机输入一个参数。" tabindex="-1">1. input函数：用于向计算机输入一个参数。 <a class="header-anchor" href="#_1-input函数-用于向计算机输入一个参数。" aria-label="Permalink to &quot;1. input函数：用于向计算机输入一个参数。&quot;">​</a></h3><p>调用格式： A=input(提示信息，选项)； 注：‘s’选项，则允许用户输入一个字符串。 例如想输入一个人的姓名，可采用命令 <code>xm=input(&#39;What&#39;&#39;s your name:&#39;,&#39;s&#39;)</code></p><h3 id="_2-pause函数-暂停程序的执行。" tabindex="-1">2． pause函数：暂停程序的执行。 <a class="header-anchor" href="#_2-pause函数-暂停程序的执行。" aria-label="Permalink to &quot;2． pause函数：暂停程序的执行。&quot;">​</a></h3><p>调用格式： <code>pause(延迟秒数)</code> 注：如果省略延迟时间，直接使用<code>pause</code>，则将暂停程序，直到用户按任一键后程序继续执行。</p><h3 id="_3-disp函数-命令窗口输出函数。" tabindex="-1">3． disp函数：命令窗口输出函数。 <a class="header-anchor" href="#_3-disp函数-命令窗口输出函数。" aria-label="Permalink to &quot;3． disp函数：命令窗口输出函数。&quot;">​</a></h3><p>调用格式：<code>disp(输出项)</code> 注：输出项为字符串或矩阵。</p><h1 id="三-程序设计" tabindex="-1">三．程序设计 <a class="header-anchor" href="#三-程序设计" aria-label="Permalink to &quot;三．程序设计&quot;">​</a></h1><h2 id="一-选择结构" tabindex="-1">（一）选择结构 <a class="header-anchor" href="#一-选择结构" aria-label="Permalink to &quot;（一）选择结构&quot;">​</a></h2><p>选择结构的语句有if语句和switch语句。</p><h3 id="_1-if语句" tabindex="-1">1． if语句 <a class="header-anchor" href="#_1-if语句" aria-label="Permalink to &quot;1． if语句&quot;">​</a></h3><h4 id="格式一" tabindex="-1">格式一： <a class="header-anchor" href="#格式一" aria-label="Permalink to &quot;格式一：&quot;">​</a></h4><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">if</span><span style="color:#839496;"> 条件</span></span>
<span class="line"><span style="color:#839496;">    语句组</span></span>
<span class="line"><span style="color:#859900;">end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h4 id="格式二" tabindex="-1">格式二： <a class="header-anchor" href="#格式二" aria-label="Permalink to &quot;格式二：&quot;">​</a></h4><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">if</span><span style="color:#839496;"> 条件</span></span>
<span class="line"><span style="color:#839496;">    语句组1</span></span>
<span class="line"><span style="color:#859900;">else</span></span>
<span class="line"><span style="color:#839496;">    语句组2</span></span>
<span class="line"><span style="color:#859900;">end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h4 id="格式三" tabindex="-1">格式三： <a class="header-anchor" href="#格式三" aria-label="Permalink to &quot;格式三：&quot;">​</a></h4><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">if</span><span style="color:#839496;"> 条件1</span></span>
<span class="line"><span style="color:#839496;">    语句组1</span></span>
<span class="line"><span style="color:#859900;">elseif</span><span style="color:#839496;"> 条件2</span></span>
<span class="line"><span style="color:#839496;">    语句组2</span></span>
<span class="line"><span style="color:#859900;">    ...</span></span>
<span class="line"><span style="color:#859900;">elseif</span><span style="color:#839496;"> 条件m</span></span>
<span class="line"><span style="color:#839496;">    语句组m</span></span>
<span class="line"><span style="color:#859900;">else</span></span>
<span class="line"><span style="color:#839496;">    语句组m+</span><span style="color:#D33682;">1</span></span>
<span class="line"><span style="color:#859900;">end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h3 id="_2-switch语句" tabindex="-1">2 switch语句 <a class="header-anchor" href="#_2-switch语句" aria-label="Permalink to &quot;2  switch语句&quot;">​</a></h3><p>switch语句根据变量或表达式的取值不同，分别执行不同的语句。其格式为：</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span>switch 表达式</span></span>
<span class="line"><span>    case 值1</span></span>
<span class="line"><span>        语句块1</span></span>
<span class="line"><span>    case 值2</span></span>
<span class="line"><span>        语句块2</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    otherwise</span></span>
<span class="line"><span>        默认语句块</span></span>
<span class="line"><span>end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h2 id="二-循环结构" tabindex="-1">（二）循环结构 <a class="header-anchor" href="#二-循环结构" aria-label="Permalink to &quot;（二）循环结构&quot;">​</a></h2><blockquote><p>实现循环结构的语句：for语句和while语句。</p></blockquote><h3 id="_1-for语句" tabindex="-1">1．for语句： <a class="header-anchor" href="#_1-for语句" aria-label="Permalink to &quot;1．for语句：&quot;">​</a></h3><p>格式：</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">for</span><span style="color:#839496;"> 循环变量 = 表达式1:表达式2:表达式3</span></span>
<span class="line"><span style="color:#839496;">    循环体语句</span></span>
<span class="line"><span style="color:#859900;">end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>注：其中表达式1的值为循环变量的初值，表达式2的值为步长，表达式3的值为循环变量的终值。步长为1时，表达式2可以省略。</p></blockquote><h3 id="_2-while语句" tabindex="-1">2． while语句 <a class="header-anchor" href="#_2-while语句" aria-label="Permalink to &quot;2． while语句&quot;">​</a></h3><p>格式为：</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#859900;">while</span><span style="color:#839496;"> (条件)</span></span>
<span class="line"><span style="color:#839496;">   循环体语句</span></span>
<span class="line"><span style="color:#859900;">end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="_3-循环的嵌套" tabindex="-1">3． 循环的嵌套 <a class="header-anchor" href="#_3-循环的嵌套" aria-label="Permalink to &quot;3． 循环的嵌套&quot;">​</a></h3><p>如果一个循环结构的循环体又包括一个循环结构，就称为循环的嵌套，或称为多重循环结构。 多重循环的嵌套层数可以是任意的。可以按照嵌套层数，分别叫做二重循环、三重循环等。处于内部的循环叫作内循环，处于外部的循环叫作外循环。</p><h1 id="四-函数文件" tabindex="-1">四．函数文件 <a class="header-anchor" href="#四-函数文件" aria-label="Permalink to &quot;四．函数文件&quot;">​</a></h1><p>函数文件是另一种形式的M文件，每一个函数文件都定义一个函数。事实上，MATLAB提供的标准函数大部分都是由函数文件定义的。</p><h2 id="_1-函数文件格式" tabindex="-1">1．函数文件格式 <a class="header-anchor" href="#_1-函数文件格式" aria-label="Permalink to &quot;1．函数文件格式&quot;">​</a></h2><p>函数文件由function语句引导，其格式为：</p><div class="language-matlab line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">matlab</span><pre class="shiki solarized-dark vp-code" tabindex="0"><code><span class="line"><span style="color:#268BD2;">function</span><span style="color:#2AA198;"> [输出形参表] = 函数名(输入形参表)</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    % 注释说明部分</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    % 函数功能描述</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    % 输入参数说明</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    % 输出参数说明</span></span>
<span class="line"><span style="color:#839496;">    </span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    % 函数体代码</span></span>
<span class="line"><span style="color:#586E75;font-style:italic;">    % 实现具体功能的MATLAB代码</span></span>
<span class="line"><span style="color:#839496;">end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>注：其中函数名的命名规则与变量名相同。输入形参为函数的输入参数，输出形参为函数的输出参数。当输出形参多于1个时，则应该用方括号括起来。</p><h2 id="_2-函数调用" tabindex="-1">2．函数调用 <a class="header-anchor" href="#_2-函数调用" aria-label="Permalink to &quot;2．函数调用&quot;">​</a></h2><p>函数文件编制好后，就可调用函数进行计算了。如上面定义ffib函数后，调用它求小于2000的Fibonacci数。 函数调用的一般格式是： <code>[输出实参表]=函数名(输入实参表)</code></p><h2 id="_3-函数所传递参数的可调性" tabindex="-1">3 ．函数所传递参数的可调性 <a class="header-anchor" href="#_3-函数所传递参数的可调性" aria-label="Permalink to &quot;3 ．函数所传递参数的可调性&quot;">​</a></h2><p>MATLAB在函数调用上有一个与众不同之处：函数所传递参数数目的可调性。凭借这一点，一个函数可完成多种功能。 在调用函数时，MATLAB用两个永久变量<code>nargin</code>和<code>nargout</code>分别记录调用该函数时的输入实参和输出实参的个数。只要在函数文件中包含这两个变量，就可以准确地知道该函数文件被调用时的输入输出参数个数，从而决定函数如何进行处理。</p><h1 id="五-全局变量和局部变量" tabindex="-1">五．全局变量和局部变量 <a class="header-anchor" href="#五-全局变量和局部变量" aria-label="Permalink to &quot;五．全局变量和局部变量&quot;">​</a></h1><p>在MATLAB中，全局变量用命令global定义。函数文件的内部变量是局部的，与其他函数文件及MATLAB工作空间相互隔离。但是，如果在若干函数中，都把某一变量定义为全局变量，那么这些函数将公用这一个变量。全局变量的作用域是整个MATLAB工作空间，即全程有效。所有的函数都可以对它进行存取和修改。因此，定义全局变量是函数间传递信息的一种手段。</p><hr>`,54)]))}const h=s(p,[["render",i]]);export{u as __pageData,h as default};
